        {
          "proposicao": "Na avaliação comparativa de opções de descomissionamento, riscos de segurança de diferentes alternativas podem ser comparados com base em princípios gerais de gestão de risco e, quando possível, com apoio de técnicas quantitativas.",
          "trechos": [
            "E58045fe3c1b4b295:0:700",
            "E58045fe3c1b4b295:700:1394"
          ],
          "condicoes": [
            "segundo o decreto estrangeiro citado no texto",
            "no contexto de comparação entre opções de descomissionamento"
          ],
          "limites": [
            "não deve ser tratado como requisito brasileiro automático",
            "o trecho não define critérios específicos para FPSO, desmontagem offshore de módulos ou manutenção de sistemas essenciais"
          ]
        },
        {
          "proposicao": "A comparação ambiental entre opções deve considerar impactos das atividades no local offshore e também no local de desmantelamento e eliminação em terra; se o local de descarte não estiver definido, o texto menciona avaliação genérica dos impactos do local de disposição.",
          "trechos": [
            "E58045fe3c1b4b295:700:1394",
            "E58045fe3c1b4b295:1394:2082"
          ],
          "condicoes": [
            "conforme a abordagem do decreto citado",
            "quando houver avaliação comparativa de alternativas"
          ],
          "limites": [
            "o trecho trata de comparação de alternativas e não de execução operacional de desmontagem offshore",
            "não indica medidas de controle para içamentos, SIMOPS ou mudança de barreiras"
          ]
        },
        {
          "proposicao": "A viabilidade técnica de diferentes opções pode ser apoiada por uso combinado de avaliação quantitativa de riscos, análises de engenharia e análises operacionais, com informações qualitativas ou quantitativas.",
          "trechos": [
            "E58045fe3c1b4b295:1394:2082",
            "E58045fe3c1b4b295:2082:2370"
          ],
          "condicoes": [
            "na estrutura de avaliação comparativa referida pelo texto"
          ],
          "limites": [
            "o excerto não informa critérios de aceitação, fórmulas ou parâmetros para distribuição de pesos, esforços globais ou resistência local",
            "é referência estrangeira e genérica, sem adaptação explícita ao arcabouço brasileiro"
          ]
        }
      ]
